def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    row_bands = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_bands.append((start, r))
        start = r + 1
    if start < h:
        row_bands.append((start, h))

    col_bands = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_bands.append((start, c))
        start = c + 1
    if start < w:
        col_bands.append((start, w))

    if not row_bands or not col_bands:
        return [row[:] for row in grid]

    tiles = []
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            score = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            tiles.append((score, ri, ci))

    _, src_ri, src_ci = max(tiles)
    sr0, sr1 = row_bands[src_ri]
    sc0, sc1 = col_bands[src_ci]
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = pattern[r - r0][c - c0]
    return out
